INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass alle Daten in einem Unternehmen denselben Sicherheitsgrad benötigen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Sensibilität"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Schutzbedarfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist zentral bei der Bewertung von Daten?', 3, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schützt sensible Informationen"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}, {"text": "Datengröße", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzziele werden typischerweise bewertet?', 5, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schützt Daten vor Fremdzugriff"}, {"text": "Integrität", "correct": true, "because": "Sichert Datenkorrektheit"}, {"text": "Verfügbarkeit", "correct": true, "because": "Gewährleistet Zugriff"}, {"text": "Schnelligkeit", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Design", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schutzbedarf hängt von Datenwert ab. b) Alle Daten haben hohen Schutzbedarf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Sicherheitsbewertung von Daten?', 4, '[{"text": "Vertraulichkeit", "correct": false, "because": "Kern des Schutzes"}, {"text": "Verfügbarkeit", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Datenfarbe", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Vertraulichkeit immer höchste Priorität hat?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Daten"}, {"text": "Ja", "correct": false, "because": "Andere Ziele oft gleich wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten haben in der Regel hohen Schutzbedarf?', 4, '[{"text": "Personenbezogene Daten", "correct": true, "because": "DSGVO fordert Schutz"}, {"text": "Öffentliche Preislisten", "correct": false, "because": "Weniger sensibel"}, {"text": "Werbebilder", "correct": false, "because": "Geringer Schutzbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Integrität nur für Finanzdaten wichtig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für andere Daten relevant"}, {"text": "Ja", "correct": false, "because": "Integrität universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird Schutzbedarf nur für IT-Systeme bewertet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Prozesse, Daten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen resultieren aus hohem Schutzbedarf?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Vertraulichkeit"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Begrenzt Zugriff"}, {"text": "Farbcodierte Server", "correct": false, "because": "Irrelevant"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Bewertung sensibler Daten?', 4, '[{"text": "Vertraulichkeit", "correct": true, "because": "Schützt vor Missbrauch"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sekundär"}, {"text": "Datenvisualisierung", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Hoher Schutzbedarf erhöht Sicherheitskosten. b) Er gilt immer für alle Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Sicherheitsbewertung?', 3, '[{"text": "Risikoanalyse", "correct": false, "because": "Bestimmt Bedarf"}, {"text": "Schutzziel", "correct": false, "because": "Definiert Anforderung"}, {"text": "Serverdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich den Schutzbedarf von Kundendaten bewerte?', 4, '[{"text": "Vertraulichkeit und Integrität prüfen", "correct": true, "because": "Sensibel nach DSGVO"}, {"text": "Nur Verfügbarkeit", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Analyse", "correct": false, "because": "Risiko für Verstöße"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schutzbedarf nur für personenbezogene Daten gilt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsdaten, Systeme"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, den Schutzbedarf zu bestimmen?', 4, '[{"text": "Risikobewertung", "correct": true, "because": "Identifiziert Bedrohungen"}, {"text": "Schnelle Analyse", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Einheitliche Regeln", "correct": false, "because": "Zu starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Verfügbarkeit für alle Daten gleich wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nutzung"}, {"text": "Ja", "correct": false, "because": "Variiert nach Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten benötigen oft hohe Verfügbarkeit?', 5, '[{"text": "Transaktionsdaten", "correct": true, "because": "Für Geschäftskontinuität"}, {"text": "Kundendaten", "correct": true, "because": "Für Zugriff"}, {"text": "Werbematerial", "correct": false, "because": "Geringer Bedarf"}, {"text": "Archivdaten", "correct": false, "because": "Seltener Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Sicherheitsbewertung unwichtig?', 3, '[{"text": "Schutzziele", "correct": false, "because": "Definieren Bedarf"}, {"text": "Risiko", "correct": false, "because": "Bestimmt Maßnahmen"}, {"text": "Dateinamen", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich den Schutzbedarf eines Systems bestimme?', 4, '[{"text": "Risiken und Schutzziele analysieren", "correct": true, "because": "Strukturierter Ansatz"}, {"text": "Nur Verschlüsselung setzen", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Ohne Bewertung", "correct": false, "because": "Riskant"}]');
